sketches.voltage/arduino:
// GENESIS measurement sketch: voltage logger for Arduino Uno / Nano
// Generated from your investigation. Board package: Arduino AVR Boards.
//
// SAFETY: the circuit's supply is 9 V (from your notes).
// Never connect more than 5 V to a Arduino Uno / Nano pin.
// Wiring:
//   the 555's pins 2 and 6 (the timing capacitor)  ->  R1 = 15 kΩ  ->  A0
//   A0  ->  R2 = 10 kΩ  ->  GND
//   circuit GND  ->  Arduino Uno / Nano GND   (shared ground is required)
// With this divider the pin sees at most about 3.96 V.
// Open the Serial Monitor (or Serial Plotter) at 115200 baud.

const int PIN = A0;
const float DIVIDER = 2.5000;   // volts at the circuit = volts at the pin x DIVIDER

float readVolts() { return analogRead(PIN) * (5.0 / 1023.0) * DIVIDER; }

void setup() {
  Serial.begin(115200);
  delay(500);
}

void loop() {
  // Serial Plotter shows three lines: the node, and where a 555's capacitor should turn around.
  Serial.print("node_V:");     Serial.print(readVolts(), 3);
  Serial.print(" third_V:");   Serial.print(3.00);
  Serial.print(" two_thirds_V:"); Serial.println(6.00);
  delay(10);   // 100 samples per second
}

